13	      type: { type: "string", enum: ["choice", "text", "blanks", "classification", "matching"], description: "Question type. Use 'classification' to assign each item to a category; use 'matching' for worksheet-style prompt-to-answer matching." },
14	      allow_text: { type: "boolean", description: "Whether to also allow free-text input (default: true if no choices, false if choices provided)" },
15	      require_reasons: { type: "boolean", description: "For classification questions, require a short justification per row (default true)." },
